(()=>{
const base='assets/manter-no-alto/',colors=['vermelho','laranja','amarelo','verde','azul','roxo','rosa','turquesa'];
let level='easy',who='bluey',state=null,raf=0,last=0,acc=0,epoch=0,owned=false,assets=null,loading=null,stage=null,context=null;
const keys=new Set(),pointers=new Map();
const files=['sala-bluey-v1.webp','bandit-deitado-v1.webp','chilli-cafe-v2.webp',...colors.map(c=>'balao-'+c+'-v1.webp'),...['bluey','bingo'].flatMap(c=>['01','02'].map(f=>c+'-perseguindo-direita-frame-'+f+'.webp'))];
function preload(){if(!loading)loading=Promise.all(files.map(f=>new Promise((resolve,reject)=>{const im=new Image(),timer=setTimeout(()=>reject(Error(f)),20000);im.onload=()=>{clearTimeout(timer);im.decode().then(()=>resolve([f,im]),reject)};im.onerror=()=>{clearTimeout(timer);reject(Error(f))};im.src=base+f}))).then(entries=>assets=Object.fromEntries(entries)).catch(e=>{loading=null;throw e});return loading;}
function release(){keys.clear();pointers.clear();}
function stop(keepFull=false){epoch++;cancelAnimationFrame(raf);state=null;release();stage=null;if(owned&&!keepFull){owned=false;try{screen.orientation?.unlock()}catch{}if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}}
function setup(){stop();memoryStop();stopSearchTimer();leaveSearchFullscreen();document.body.dataset.section='keepup';app.innerHTML='<section class="ku-setup"><button class="ku-back">← Jogos</button><p>BLUEY E BINGO · UMA BRINCADEIRA EM FAMÍLIA</p><h1>Manter no Alto <span>🎈</span></h1><h2>Escolha o desafio</h2><div class="ku-options">'+[['easy','Fácil',10],['medium','Médio',8],['hard','Difícil',6]].map(([id,name,seconds])=>'<button data-ku-level="'+id+'"><b>'+name+'</b><small>Um novo balão a cada '+seconds+' segundos</small></button>').join('')+'</div><p>Não deixe nenhum balão tocar o chão!</p></section>';app.querySelector('.ku-back').onclick=home;app.querySelectorAll('[data-ku-level]').forEach(b=>b.onclick=()=>{level=b.dataset.kuLevel;characters()});preload().catch(()=>{});}
function characters(){app.innerHTML='<section class="ku-setup"><button class="ku-back">← Dificuldade</button><p>MANTER NO ALTO</p><h1>Quem vai brincar?</h1><div class="ku-options ku-characters">'+['bluey','bingo'].map(c=>'<button data-ku-who="'+c+'"><img src="'+base+c+'-oficial.webp" alt="'+c+'"><b>'+c[0].toUpperCase()+c.slice(1)+'</b></button>').join('')+'</div><p>Use ← → no teclado ou segure as setas na tela.</p><small>Retratos: <a href="https://www.bluey.tv/characters/" target="_blank" rel="noopener">Bluey · site oficial</a></small></section>';app.querySelector('.ku-back').onclick=setup;app.querySelectorAll('[data-ku-who]').forEach(b=>b.onclick=()=>{who=b.dataset.kuWho;start()});}
function resize(){if(!stage)return;const w=visualViewport?.width||innerWidth,h=visualViewport?.height||innerHeight,rotated=w<h;stage.classList.toggle('ku-rotated',rotated);stage.style.width=(rotated?h:w)+'px';stage.style.height=(rotated?w:h)+'px';const scale=Math.min((rotated?h:w)/1600,(rotated?w:h)/900);stage.querySelector('.ku-world').style.transform='translate(-50%,-50%) scale('+scale+')';}
function fullscreen(){if(!matchMedia('(pointer:coarse)').matches||document.fullscreenElement)return;try{const id=epoch;Promise.resolve(document.documentElement.requestFullscreen?.()).then(()=>{if(id!==epoch){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});return}owned=!!document.fullscreenElement;if(owned)try{Promise.resolve(screen.orientation?.lock?.('landscape')).catch(()=>{})}catch{}resize()}).catch(()=>{});}catch{}}
async function start(){stop(true);const id=epoch;document.body.dataset.section='keepup';app.innerHTML='<section class="ku-stage"><div class="ku-world"><canvas width="1600" height="900" aria-label="Mantenha os balões no alto"></canvas><div class="ku-hud"><button id="ku-exit">← Voltar</button><span id="ku-score">Preparando a sala…</span></div><button class="ku-arrow ku-left" data-dir="-1" aria-label="Correr para a esquerda">❮</button><button class="ku-arrow ku-right" data-dir="1" aria-label="Correr para a direita">❯</button><div class="ku-overlay" role="status">Preparando a sala…</div></div></section>';stage=app.querySelector('.ku-stage');context=stage.querySelector('canvas').getContext('2d');stage.querySelector('#ku-exit').onclick=()=>{stop();characters()};stage.querySelectorAll('[data-dir]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,+b.dataset.dir)};for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,e=>pointers.delete(e.pointerId));});resize();fullscreen();try{await preload();if(id!==epoch)return;stage.querySelector('.ku-overlay').remove();state=KeepUpCore.create(level);last=0;acc=0;raf=requestAnimationFrame(tick);}catch{if(id!==epoch)return;const overlay=stage.querySelector('.ku-overlay');overlay.innerHTML='<p>Uma imagem não carregou.</p><button>Tentar novamente</button>';overlay.querySelector('button').onclick=start;}}
function sprite(file,x,y,w,h,flip=false){const im=assets[file];context.save();if(flip){context.translate(x+w,y);context.scale(-1,1);context.drawImage(im,0,0,w,h)}else context.drawImage(im,x,y,w,h);context.restore();}
function draw(){context.clearRect(0,0,1600,900);sprite('sala-bluey-v1.webp',0,0,1600,900);sprite('bandit-deitado-v1.webp',300,330,420,210);sprite('chilli-cafe-v2.webp',28,300,187,280);
 for(const b of state.balloons){sprite('balao-'+colors[b.color]+'-v1.webp',b.x-67,b.y-80,134,160);}
 const p=state.player,frame=Math.abs(p.vx)>15&&Math.floor(p.stride/65)%2?'02':'01';sprite(who+'-perseguindo-direita-frame-'+frame+'.webp',p.x-130,620,260,260,p.face<0);
 stage.querySelector('#ku-score').textContent=Math.floor(state.elapsed)+' s · '+state.hits+' toques · '+state.balloons.length+' balões';}
function tick(now){if(!state)return;if(!document.hidden){if(last)acc+=Math.min((now-last)/1000,.05);const left=keys.has('ArrowLeft')||keys.has('a')||[...pointers.values()].includes(-1),right=keys.has('ArrowRight')||keys.has('d')||[...pointers.values()].includes(1);while(acc>=1/120&&!state.over){KeepUpCore.step(state,1/120,Number(right)-Number(left));acc-=1/120;}draw();if(state.over){release();const overlay=document.createElement('div');overlay.className='ku-overlay';overlay.innerHTML='<div><h2>Vamos tentar de novo?</h2><p>Você manteve os balões no alto por '+Math.floor(state.elapsed)+' segundos!</p><button id="ku-again">Brincar de novo</button><button id="ku-choose">Trocar personagem</button></div>';stage.querySelector('.ku-world').append(overlay);overlay.querySelector('#ku-again').onclick=start;overlay.querySelector('#ku-choose').onclick=()=>{stop();characters()};return;}}last=now;raf=requestAnimationFrame(tick);}
window.addEventListener('keydown',e=>{if(!state||!['ArrowLeft','ArrowRight','a','d'].includes(e.key))return;e.preventDefault();keys.add(e.key)});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',release);document.addEventListener('visibilitychange',()=>{release();last=0;acc=0});window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);document.addEventListener('fullscreenchange',resize);
const oldHome=home;home=function(){stop();oldHome();const cards=app.querySelector('.game-cards');if(cards){cards.insertAdjacentHTML('beforeend','<button class="game-card ku-portal" id="ku-open"><div class="game-cover ku-cover"><img src="'+base+'sala-bluey-v1.webp" alt="Sala da Bluey"><img class="ku-cover-balloon" src="'+base+'balao-vermelho-v1.webp" alt=""><span class="cover-badge">🎈 NÃO DEIXE CAIR</span></div><div class="game-card-copy"><small>UMA BRINCADEIRA EM FAMÍLIA</small><h2>Manter no Alto <span>↗</span></h2><p>Corra com Bluey e Bingo para salvar os balões!</p></div></button>');app.querySelector('#ku-open').onclick=setup;}};
const oldCatalog=showCatalog;showCatalog=function(){stop();oldCatalog()};home();
})();
